def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core_pre = v.split('+', 1)[0]
        if '-' in core_pre:
            core, pre = core_pre.split('-', 1)
        else:
            core, pre = core_pre, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            pre_flag = 1  # no prerelease sorts after
            pre_tuple = ()
        else:
            pre_flag = 0
            ids = pre.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))
            pre_tuple = tuple(pre_ids)

        return (major, minor, patch, pre_flag, pre_tuple)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

